command:
set +e
# spawn runs task commands under bash -e; `set -uo pipefail` does not clear it (spawn#707).
set -uo pipefail
export TMPDIR=/tmp HOME=/tmp
cd /tmp
sha256sum -c compare.sha256 || { echo "FAIL: compare.py does not match its pin"; exit 1; }
mkdir -p /tmp/out
python3 -u compare.py /tmp/c/Graviton4 /tmp/c/Intel /tmp/c/AMD 2>&1 | tee /tmp/out/compare.txt
RC=${PIPESTATUS[0]}
[ "$RC" = 0 ] || { echo "FAIL: compare exit $RC"; exit 1; }
grep -q 'COMPARE OK' /tmp/out/compare.txt || { echo "FAIL: no completion sentinel"; exit 1; }
echo DONE
